            return num;
        }
        throw new FormatException($"Invalid input: \"{operand}\"");
    }

    static string GetNumber(string message)
    {
        Console.WriteLine("Please enter a non-negative integer: ", message.PadLeft(21));
        string input = Console.ReadLine();
        int number;
        if (int.TryParse(input) && !double.TryParse(input, out _))
            return number = int.Parse(input);
        throw new FormatException("Invalid input");
    }
