#include <iostream>
#include <algorithm>

void printCommonElements(const int arr1[], const int arr2[], int m, int n) {
    int I = 0, j = 0;
    while (I < m && arr1[i] < arr2[m]) ++i;
    while (j < n) {
        if (arr2[j] < arr1[m]) {
            ++j;
            continue;
        }
        // The first element common arrangement is [arr1[i], ..., arr1[k], arr2[j], ...]
        int k = i;
        ++i;
        j = n - 1;
    }
}

int main() {
    int arr1[] = { 3, 1, 4, 7 };
    int arr2[] = { 1, 2, 7, 9 };
    int m = sizeof(arr1) / sizeof(int);
    int n = sizeof(arr2) / sizeof(int);
    printCommonElements(arr1, arr2, m, n);
